-- Expand original About copy without overwriting administrator edits.
UPDATE site_content SET value=json_set(value, '$.aboutTitle', 'Песни, в которых
узнают вашу историю.') WHERE id=1 AND json_extract(value, '$.aboutTitle')='За каждой песней —
ваша история.';
UPDATE site_content SET value=json_set(value, '$.aboutLead', 'SSoundCheck помогает превратить ваши слова, чувства и воспоминания в личную песню. Здесь можно заказать текст, добавить музыку к своим словам или создать песню с нуля — для любимого человека, семьи, важного события или себя. Не нужно уметь писать стихи или разбираться в музыке: достаточно рассказать, что вы хотите сказать.') WHERE id=1 AND json_extract(value, '$.aboutLead')='SSoundCheck — музыкальный проект для тех, кто хочет превратить свою историю в песню: для близкого человека, особенного события или себя.';
UPDATE site_content SET value=json_set(value, '$.aboutCopy', 'Вы делитесь историей, выбираете настроение и рассказываете, какое звучание вам близко. Мы готовим текст и создаём музыку и вокал с помощью ИИ под вашу задачу. Для заказа песни сначала передаём 40-секундный фрагмент: вы слушаете его, а после подтверждения оплаты получаете полный трек для прослушивания и скачивания. Если хочется что-то изменить, обсуждаем правки в рамках выбранного тарифа.') WHERE id=1 AND json_extract(value, '$.aboutCopy')='Вы делитесь идеей, задаёте тему и настроение. Мы создаём текст и подбираем направление звучания. Музыку и вокал создаём с помощью ИИ — под согласованную задачу.';
